INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'Science-based adaptive endurance training plans for runners, cyclists, triathletes and rowers: the plan adjusts to your fitness, fatigue and schedule, and a conversational AI coach explains your data.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Athletica is an adaptive endurance training system for runners, cyclists, triathletes, duathletes, rowers and hybrid athletes, as well as coaches who value long-term progress. Plans automatically adjust to your fitness, fatigue and schedule so you improve with confidence. A missed workout, a travel day or bad sleep doesn''t blow up the plan; the system adapts it, helping you stay consistent, avoid burnout and arrive at race day prepared. A conversational AI coach understands your training history, fitness and fatigue: you can ask a question and get a real answer based on your data instead of just a set of numbers. Every plan includes full platform access with no tiers. There is a two-week free trial with no credit card.', 'manual' FROM DUAL WHERE @new = 1;
