-- Athlytic — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'athlyticapp.com' OR LOWER(`name`) = LOWER('Athlytic'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Athlytic', NULL, 'https://athlyticapp.com', NULL, NULL, 'Застосунок для Apple Watch, який перетворює дані Apple Health на щоденні тренувальні підказки: показник відновлення зранку, цільова зона навантаження на день, навантаження наживо на зап''ясті та аналіз сну.', 'An Apple Watch app that turns Apple Health data into daily training guidance: a morning recovery score, a target exertion zone for the day, live exertion on your wrist and sleep analysis.', 'Athlytic допомагає зрозуміти, коли варто тренуватися інтенсивно, коли збавити оберти й наскільки сильно навантажувати себе сьогодні. Застосунок бере дані з Apple Health і зранку показує один зрозумілий показник відновлення від 0 до 100%, розрахований на основі варіабельності серцевого ритму й пульсу спокою під час сну. Відновлення перетворюється на персональну цільову зону навантаження на день, а під час тренування навантаження накопичується в реальному часі на годиннику, тож видно, коли ціль досягнута. Щоденна панель показує чотири ключові числа: відновлення, кардіонавантаження за шкалою 0–10, цільову зону й якість сну з урахуванням недосипу та регулярності. Також є журнал з аналізом впливу звичок, цілодобовий моніторинг здоров''я, відстеження тренувань, «вік Athlytic» і тренування з урахуванням менструального циклу. Є віджети для Apple Watch.', 'Athlytic helps you know when to push, when to back off and how hard to go today. The app uses your Apple Health data and each morning shows one clear recovery score from 0 to 100%, based on heart rate variability and resting heart rate during sleep. Recovery becomes a personalized Target Exertion Zone for the day, and during workouts exertion builds in real time on your watch so you can see when you hit the zone. The daily dashboard shows four key numbers: recovery, cardiovascular exertion on a 0–10 scale, the target zone and sleep quality including sleep debt and consistency. There is also a journal with impact analysis, 24/7 health monitoring, workout tracking, an Athlytic Age and cycle-aware training. Apple Watch widgets are available.', 'Щоденний показник відновлення
Персональна цільова зона навантаження
Навантаження наживо на Apple Watch
Аналіз сну, недосипу й регулярності
Журнал і аналіз впливу звичок
Тренування з урахуванням циклу
Віджети для годинника', 'Daily recovery score
Personalized target exertion zone
Live exertion on Apple Watch
Sleep, sleep debt and consistency analysis
Journal and habit impact analysis
Cycle-aware training
Watch widgets', 'Власники Apple Watch, які тренуються й хочуть розумно чергувати навантаження й відновлення.', 'Apple Watch owners who train and want to balance effort and recovery wisely.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
