-- Bevel — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bevel.health' OR LOWER(`name`) = LOWER('Bevel'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Bevel', NULL, 'https://bevel.health', NULL, NULL, 'AI-коуч зі здоров''я, який об''єднує дані носимих пристроїв, аналізи крові й спосіб життя: показники навантаження, сну й відновлення, облік харчування, медичні записи в одному місці та персональні поради цілодобово.', 'An AI health coach that brings together wearable data, bloodwork and lifestyle: strain, sleep and recovery scores, meal tracking, medical records in one place and personal guidance around the clock.', 'Bevel допомагає розібратися у власних даних про здоров''я — від носимих пристроїв до аналізів крові. Сигнали тіла перетворюються на зрозумілі показники: навантаження одним числом відображає щоденні зусилля, розділ сну показує фази й потребу у відпочинку, а відновлення підказує, чи готові ви до активного дня, чи краще збавити темп. Можна записувати прийоми їжі й бачити, що саме дає енергію організму, а також зберігати аналізи, клінічні нотатки й медичні записи в одному захищеному місці. Bevel Intelligence — персональний коуч, доступний цілодобово: відповідає на запитання з опорою на ваші показники, сам надсилає нагадування, щоденні підсумки й підказки та посилається на надійні джерела. Застосунок працює з популярними носимими пристроями; почати можна безкоштовно.', 'Bevel helps you make sense of your health data, from wearables to bloodwork. Your body''s signals become clear metrics: Strain captures your daily effort in one number, Sleep shows your stages and sleep needs, and Recovery tells you whether you''re ready to take on the day or should slow down. You can log meals and see what''s fueling your body, and keep labs, clinical notes and medical records in one secure place. Bevel Intelligence is a personal coach available 24/7: it answers questions grounded in your own metrics, proactively sends reminders, daily summaries and nudges, and points to trusted sources. The app works with popular wearables, and you can start for free.', 'Показники навантаження, сну й відновлення
Облік харчування
Зберігання аналізів і медичних записів
Персональний AI-коуч цілодобово
Відповіді на основі ваших даних
Щоденні підсумки й нагадування
Підключення носимих пристроїв', 'Strain, sleep and recovery scores
Meal tracking
Storage for labs and medical records
Personal AI coach 24/7
Answers based on your own data
Daily summaries and reminders
Wearable integrations', 'Люди, які користуються носимими пристроями й хочуть зрозуміло бачити своє навантаження, сон, відновлення й здоров''я.', 'People who use wearables and want a clear view of their strain, sleep, recovery and health.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
