INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Bevel helps you make sense of your health data, from wearables to bloodwork. Your body''s signals become clear metrics: Strain captures your daily effort in one number, Sleep shows your stages and sleep needs, and Recovery tells you whether you''re ready to take on the day or should slow down. You can log meals and see what''s fueling your body, and keep labs, clinical notes and medical records in one secure place. Bevel Intelligence is a personal coach available 24/7: it answers questions grounded in your own metrics, proactively sends reminders, daily summaries and nudges, and points to trusted sources. The app works with popular wearables, and you can start for free.', 'manual' FROM DUAL WHERE @new = 1;
