-- Catapult — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'catapult.com' OR LOWER(`name`) = LOWER('Catapult'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Catapult', NULL, 'https://catapult.com', NULL, NULL, 'Спортивні технології для команд: системи моніторингу спортсменів з GPS і локальним позиціонуванням, пульсом і понад 15 показниками наживо, відеоаналіз, рішення для скаутингу й рекрутингу. Працює з елітними командами в понад 40 видах спорту.', 'Sports technology for teams: athlete monitoring systems with GPS and local positioning, heart rate and 15+ live metrics, video analysis and scouting and recruiting solutions. Used by elite teams in 40+ sports.', 'Catapult — глобальна компанія спортивних технологій, яка допомагає лігам, командам і організаціям розкривати потенціал спортсменів за допомогою даних і аналітики. Основний напрям — моніторинг спортсменів: флагманське рішення Vector Pro відстежує спортсменів на відкритих полях і в приміщеннях за допомогою GPS і локальної системи позиціонування, вимірює пульс, інерційні дані й понад 15 показників у реальному часі та інтегрується з відеоаналізом, щоб пояснювати дані через відео. Vector Core пропонує більшість цих можливостей у компактнішому пакеті. Окрім моніторингу, є платформа відеоаналізу, рішення для скаутингу й рекрутингу та для автоспорту. Catapult має рішення для футболу, американського футболу, регбі, хокею, крикету, бейсболу й баскетболу та працює з тисячами елітних команд у більш ніж сотні країн. Ціни формуються індивідуально.', 'Catapult is a global sports technology company that helps leagues, teams and organizations unlock athlete potential with data and analytics. Its core is athlete monitoring: the flagship Vector Pro tracks athletes outdoors and indoors using GPS and a local positioning system, measures heart rate, inertial data and more than 15 live metrics, and integrates with video analysis to put athlete data in context. Vector Core offers many of the same features in a more compact package. Beyond monitoring there is a video analysis platform, scouting and recruitment solutions and motorsport solutions. Catapult serves football, American football, rugby, ice hockey, cricket, baseball and basketball and works with thousands of elite teams in more than a hundred countries. Pricing is tailored to each team.', 'Моніторинг спортсменів із GPS і локальним позиціонуванням
Відстеження на полі й у приміщенні
Пульс і понад 15 показників наживо
Інтеграція з відеоаналізом
Скаутинг і рекрутинг
Рішення для багатьох видів спорту', 'Athlete monitoring with GPS and local positioning
Outdoor and indoor tracking
Heart rate and 15+ live metrics
Video analysis integration
Scouting and recruiting
Solutions for many sports', 'Професійні й університетські команди, ліги та спортивні організації.', 'Pro and college teams, leagues and sports organizations.', 'web,mobile', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
