SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'coros.com' OR LOWER(`name`) = LOWER('COROS'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'COROS', NULL, 'https://coros.com', NULL, NULL, 'Спортивні GPS-годинники, пульсометр і тренувальні інструменти для бігунів, велосипедистів, скелелазів і всіх спортсменів на витривалість: моделі для бігу, трейлу й пригод, а також плани тренувань і тренування від тренерів.', 'GPS sports watches, a heart rate monitor and training tools for runners, cyclists, climbers and all endurance athletes: models for road, trail and adventure, plus coach-made training plans and workouts.', 'COROS створює спортивні технології для бігунів, велосипедистів, скелелазів і всіх спортсменів на витривалість, розраховані на роботу в екстремальних умовах. Лінійка годинників охоплює PACE 4 Pro — флагман з AMOLED-екраном для тих, хто прагне максимальних результатів без зайвої ваги, ультралегкий PACE 4, створений разом з олімпійським чемпіоном, APEX 4 для перегонів і тренувань у горах, VERTIX 2S для тих, хто хоче все й одразу, і пригодницький NOMAD. Є також пульсометр на руку для точних даних. Окремий розділ — плани тренувань і готові тренування, розроблені тренерами й перевірені спортсменами, наприклад плани підготовки до напівмарафону за темпом чи за пульсом. Обладнання можна обрати за видом спорту: шосейний біг, трейл, скелелазіння, велоспорт.', 'COROS builds sports technology for runners, cyclists, climbers and all endurance athletes, designed to perform in extreme conditions. The watch lineup includes the PACE 4 Pro, an AMOLED flagship for athletes seeking peak performance without the weight, the ultralight PACE 4 created with an Olympic champion, the APEX 4 for racing and training in the mountains, the VERTIX 2S for athletes who want it all, and the adventure-ready NOMAD. There is also an arm-worn heart rate monitor for precise data. A separate section offers training plans and workouts made by coaches and proven by athletes, such as half-marathon plans by pace or heart rate. You can shop by sport: road running, trail running, climbing and cycling.', 'GPS-годинники для бігу, трейлу й гір
Пульсометр на руку
Плани тренувань від тренерів
Готові тренування
Моделі для екстремальних умов
Вибір обладнання за видом спорту', 'GPS watches for road, trail and mountains
Arm-worn heart rate monitor
Coach-made training plans
Ready-made workouts
Models for extreme conditions
Shop by sport', 'Бігуни, трейлраннери, велосипедисти, скелелази й інші спортсмени на витривалість.', 'Runners, trail runners, cyclists, climbers and other endurance athletes.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
