SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'elitehrv.com' OR LOWER(`name`) = LOWER('Elite HRV'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Elite HRV', NULL, 'https://elitehrv.com', NULL, NULL, 'Застосунок для вимірювання варіабельності серцевого ритму: щоденний показник готовності, біологічний зворотний зв''язок наживо, аналітика трендів стресу й відновлення без цілодобового носіння пристроїв. Особистий застосунок безкоштовний, є командні плани.', 'A heart rate variability app: a daily readiness score, live biofeedback and stress and recovery trend analytics without wearing a device 24/7. The personal app is free and team plans are available.', 'Elite HRV — застосунок для точного відстеження варіабельності серцевого ритму, який дає глибоке розуміння здоров''я, стресу, відновлення й балансу нервової системи. Він пропонує персональні щоденні рекомендації для довголіття й стабільних результатів: допомагає контролювати стрес, швидше відновлюватися й уникати хвороб. У застосунку є щоденний індикатор готовності, біологічний зворотний зв''язок у реальному часі, аналітика й тренди, а носити пристрій цілодобово не потрібно. Особистий застосунок безкоштовний і безлімітний: точний збір даних, готовність і деталі HRV, мітки, персональні висновки й тренди, хмарне збереження й експорт сирих даних. Тариф Personal Pro додає веб-панель із поглибленою аналітикою й порівняннями, а Team Pro — інструменти для тренерів і команд. Компанія також розробляє Spren — оцінку складу тіла за селфі.', 'Elite HRV is an app for accurate heart rate variability tracking that gives deep insight into your health, stress, recovery and nervous system balance. It offers personalized daily guidance for longevity and lifelong performance, helping you manage stress, recover faster and avoid illness. The app includes a daily readiness gauge, live biofeedback, trending and analytics, and doesn''t require a 24/7 wearable. The personal app is free and unlimited: accurate data capture, readiness and HRV details, tagging, personal insights and trends, cloud backups and raw data export. Personal Pro adds a web dashboard with advanced analytics and comparisons, and Team Pro adds tools for coaches and teams. The company also develops Spren, a body composition scan from a selfie.', 'Вимірювання варіабельності серцевого ритму
Щоденний показник готовності
Біологічний зворотний зв''язок наживо
Тренди стресу й відновлення
Без цілодобового носіння пристроїв
Веб-панель із поглибленим аналізом
Командні плани для тренерів', 'Heart rate variability measurement
Daily readiness score
Live biofeedback
Stress and recovery trends
No 24/7 wearable needed
Web dashboard with advanced analysis
Team plans for coaches', 'Спортсмени, тренери, команди й усі, хто хоче стежити за стресом і відновленням.', 'Athletes, coaches, teams and anyone who wants to monitor stress and recovery.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
