INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Hexis helps athletes and teams personalize and periodize their fueling and recovery strategies. Almost every endurance athlete has a training plan, but very few have a fueling plan, and Hexis fills that gap. It builds personal plans from your training data and the science behind elite sport. The core idea is Carb Coding: hard days and rest days shouldn''t be fueled the same, so each meal gets a color based on the work you''ve just done and the work ahead. Green means high carb before a hard or long session, amber means moderate carb for steady training, and red means low carb on an easy or rest day. Running, swimming, strength, cycling and more than 80 other activities are supported. Hexis integrates with Garmin, TrainingPeaks, Intervals.icu, WHOOP and Apple Health. A free fuel plan calculator is available.', 'manual' FROM DUAL WHERE @new = 1;
