SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'humango.ai' OR LOWER(`name`) = LOWER('HumanGO'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'HumanGO', NULL, 'https://humango.ai', NULL, NULL, 'AI-застосунок для тренувань на витривалість: складає гіперперсоналізований план, який підлаштовується під ваш графік, втому й показники здоров''я, прогнозує форму, а AI-тренер Hugo дає миттєвий відгук. Є версії для спортсменів, тренерів і команд.', 'An AI app for endurance training: it builds a hyper-personalized plan that adapts to your schedule, fatigue and health metrics, predicts your fitness, and the AI coach Hugo gives instant feedback. Versions for athletes, coaches and teams.', 'HumanGO — тренувальний застосунок на основі штучного інтелекту, який будує гіперперсоналізовані адаптивні плани під ваші цілі й життя, а не навпаки. Ви ставите цілі й ключові старти, вказуєте свою доступність на тиждень і підключаєте носимі пристрої та інші тренувальні сервіси. План підлаштовується під графік, поїздки й поточний стан, відстежує ключові показники здоров''я, допомагає контролювати втому й прогнозує, як зміниться ваша форма. AI-тренер Hugo дає миттєвий відгук і поради, помічає, коли ви пропускаєте тренування, і коригує навантаження відповідно до вашого стану — з ним можна навіть посперечатися. Можна приєднуватися до груп. Окремі можливості передбачені для спортсменів, тренерів і команд. Є безкоштовний пробний період.', 'HumanGO is an AI-powered training app that builds hyper-personalized adaptive plans around your goals and life, not the other way around. You set your goals and key races, enter your weekly availability and connect wearables and other training tools. The plan adapts to your schedule, travel and current state, monitors key health metrics, helps you stay on top of fatigue and predicts how your fitness will change. Hugo, the AI coach, gives instant feedback and guidance, notices when you''re slacking off and adjusts training to your state, and you can even debate with him. You can join groups. There are dedicated features for athletes, coaches and teams. A free trial is available.', 'Гіперперсоналізовані адаптивні плани
Урахування графіка й доступності
Контроль втоми й показників здоров''я
Прогноз фізичної форми
AI-тренер Hugo
Підключення носимих пристроїв
Версії для тренерів і команд', 'Hyper-personalized adaptive plans
Plans around your schedule and availability
Fatigue and health metric monitoring
Fitness prediction
Hugo AI coach
Wearable integrations
Versions for coaches and teams', 'Спортсмени на витривалість, тренери й команди.', 'Endurance athletes, coaches and teams.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
