-- JOIN — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'join.cc' OR LOWER(`name`) = LOWER('JOIN'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'JOIN', NULL, 'https://join.cc', NULL, NULL, 'AI-тренер для велосипедистів: складає персональний план під ваш графік і цілі, перебудовує тренування, коли змінюються доступні дні й години, допомагає уникати перетренованості й синхронізується зі Strava та улюбленими пристроями.', 'An AI coach for cyclists: it builds a personal plan around your schedule and goals, rebuilds workouts when your available days and hours change, helps avoid overtraining and syncs with Strava and your favorite devices.', 'JOIN — застосунок для велотренувань зі штучним інтелектом, розроблений провідними тренерами з велоспорту. Він працює як професійний тренер у кишені для велосипедистів будь-якого рівня — від новачків до елітних спортсменів. Застосунок складає адаптивні плани й ефективні тренування під ваші цілі, а коли ви змінюєте доступні дні й години, автоматично перераховує тренування під наявний час. План вивчає вас під час заїздів і враховує ваші сильні й слабкі сторони, допомагаючи прогресувати максимально й уникати перетренованості. JOIN легко поєднується з популярними застосунками й пристроями, зокрема зі Strava. Є один тариф з усіма преміум-інструментами без поділу на рівні — з помісячною або річною оплатою.', 'JOIN is an AI cycling training app designed by leading cycling coaches. It works like a professional coach in your pocket for cyclists of every level, from beginners to elite athletes. The app builds adaptive plans and efficient workouts around your goals, and when you change your available days and hours it automatically recalculates workouts for the time you have. The plan learns about you as you ride and caters to your strengths and weaknesses, helping you maximize progress and avoid overtraining. JOIN connects seamlessly with popular apps and devices, including Strava. There is one plan with all premium tools and no tiers, billed monthly or yearly.', 'Адаптивні плани під графік і цілі
Автоматичний перерахунок тренувань
Урахування сильних і слабких сторін
Профілактика перетренованості
Інтеграція зі Strava та пристроями
Для велосипедистів будь-якого рівня', 'Adaptive plans for your schedule and goals
Automatic workout recalculation
Caters to strengths and weaknesses
Overtraining prevention
Strava and device integrations
For cyclists of every level', 'Велосипедисти від новачків до досвідчених спортсменів, зокрема ті, хто тренується при щільному графіку.', 'Cyclists from beginners to experienced athletes, including those training around a busy schedule.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
