SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kinexon-sports.com' OR LOWER(`name`) = LOWER('KINEXON'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'KINEXON', NULL, 'https://kinexon-sports.com', NULL, NULL, 'Технології для професійних команд і ліг: відстеження гравців і м''яча в реальному часі, аналітика фізичних і тактичних показників, системи для суддівства з точністю до мілісекунд і рішення для залучення вболівальників.', 'Technology for pro teams and leagues: real-time player and ball tracking, analytics of physical and tactical performance, millisecond-accurate officiating systems and fan engagement solutions.', 'KINEXON Sports — технологічний партнер професійних команд, ліг і федерацій у відстеженні гравців і м''яча в реальному часі, поглибленій аналітиці результатів і сучасних рішеннях для вболівальників. Для команд є системи KINEXON PERFORM на основі локального позиціонування, інерційних датчиків і GPS, а також KINEXON COMPETE Vision для тактичної аналітики. Тренери отримують дані, які допомагають ухвалювати обґрунтовані рішення щодо здоров''я, результатів і доступності спортсменів. Для ліг і федерацій є KINEXON ENGAGE для залучення вболівальників і KINEXON OFFICIATE для суддівства з точністю до мілісекунд. Рішення підтримують футбол, баскетбол, гандбол, американський футбол, хокей і волейбол; їм довіряють сотні команд по всьому світу. Можна замовити демонстрацію.', 'KINEXON Sports is a technology partner for pro teams, leagues and federations in real-time player and ball tracking, advanced performance analytics and next-gen fan engagement. Teams get KINEXON PERFORM systems based on local positioning, inertial sensors and GPS, plus KINEXON COMPETE Vision for tactical analytics. Coaches get data that supports informed decisions about athlete health, performance and availability. Leagues and federations get KINEXON ENGAGE for fan engagement and KINEXON OFFICIATE for millisecond-accurate officiating. The solutions support football, basketball, handball, American football, hockey and volleyball and are trusted by hundreds of teams worldwide. Demos are available.', 'Відстеження гравців і м''яча в реальному часі
Системи на основі локального позиціонування, датчиків і GPS
Тактична аналітика
Дані про здоров''я й доступність спортсменів
Технології для суддівства
Рішення для залучення вболівальників', 'Real-time player and ball tracking
Systems based on local positioning, sensors and GPS
Tactical analytics
Athlete health and availability data
Officiating technology
Fan engagement solutions', 'Професійні команди, ліги й федерації в командних видах спорту.', 'Pro teams, leagues and federations in team sports.', 'web', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
