-- Kitman Labs — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kitmanlabs.com' OR LOWER(`name`) = LOWER('Kitman Labs'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kitman Labs', NULL, 'https://kitmanlabs.com', NULL, NULL, 'Інтелектуальна платформа для спорту й оборонного сектору: об''єднує дані про спортсменів і організацію в єдину картину, допомагає фахівцям співпрацювати й складати індивідуальні плани для покращення результатів.', 'An intelligence platform for sport and defense: it unifies athlete and organizational data into one view, helps practitioners collaborate and builds custom plans to improve performance.', 'Kitman Labs створили практики й науковці з даних, які шукали відповідь на питання, як оптимізувати людські досягнення. Компанія розвиває універсальну інтелектуальну платформу — інтегровану операційну систему для окремих спортсменів і команд високого рівня. Платформа дає цілісний і єдиний погляд на кожну людину й на всю організацію, щоб усі фахівці бачили дані однаково, співпрацювали й прогресували швидше. Дані слугують відправною точкою для індивідуальних планів для ліг, керівних органів, клубів і команд, а власні технології та експертиза компанії допомагають досягати високих результатів у спорті й оборонному секторі. Платформу використовують, зокрема, клуби й академії футбольної ліги MLS NEXT.', 'Kitman Labs was founded by practitioners and data scientists consumed by the question of how to optimize human achievement. The company builds an all-in-one intelligence platform, an integrated operating system for high-performing individuals and teams. The platform provides a holistic, unified view of each individual and the whole organization, so all practitioners see the data the same way, collaborate and progress faster. Data is the starting point for custom plans for leagues, governing bodies, clubs and teams, and the company''s proprietary technology and expertise help achieve top outcomes in sport and defense. The platform is used, for example, by MLS NEXT clubs and academies.', 'Єдина платформа даних про спортсменів
Цілісний погляд на спортсмена й організацію
Спільна робота фахівців
Індивідуальні плани для клубів і ліг
