SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'stryd.com' OR LOWER(`name`) = LOWER('Stryd'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Stryd', NULL, 'https://stryd.com', NULL, NULL, 'Датчик потужності бігу, який кріпиться до кросівки: у реальному часі показує потужність і тримає вас у правильній зоні зусилля, а адаптивні тренування й плани на забіги підлаштовуються під вашу форму, графік і цілі.', 'A running power meter that clips to your shoe: it shows power in real time and keeps you in the right effort zone, while adaptive training and race plans adjust to your fitness, schedule and goals.', 'Stryd — вимірювач потужності для бігу, який допомагає точно тримати темп, щоб бігати швидше, сильніше й довше. Датчик за секунди кріпиться до взуття й з''єднується з годинником без складних налаштувань. Під час кожного бігу чи забігу він у реальному часі показує потужність і підказує правильну зону зусилля — від легкого відновлювального бігу до інтенсивних інтервалів, допомагаючи бігти рівно. Функція адаптивних тренувань створює персональні заняття, що підлаштовуються під вашу форму, розклад і цілі, з гнучким графіком і відстеженням прогресу. Плани на конкретні забіги на основі потужності допомагають вийти на пік форми до старту. Новий датчик Stryd 5.0 дає ще точніші дані, а продукт Stryd Speed використовує 3D-аналіз руху для розвитку швидкості.', 'Stryd is a running power meter that paces you precisely so you can run faster, stronger and longer. The sensor clips onto your shoe in seconds and pairs with your watch with no complicated setup. On every run or race it shows your power in real time and keeps you in the right effort zone, from easy recovery runs to hard intervals, helping you pace evenly. Adaptive Training creates personalized workouts that adapt to your fitness, schedule and goals, with adaptive scheduling and progress tracking. Power-based race plans help you peak for each event. The new Stryd 5.0 delivers even more precise data, and Stryd Speed uses 3D motion to help develop speed.', 'Датчик потужності на кросівку
Потужність бігу в реальному часі
Підказки щодо зони зусилля
Адаптивні персональні тренування
Плани на забіги на основі потужності
Відстеження прогресу
Інтеграція з годинниками', 'Shoe-mounted power meter
Real-time running power
Effort zone guidance
Adaptive personal workouts
Power-based race plans
Progress tracking
Watch integration', 'Бігуни-аматори й спортсмени, які хочуть тренуватися й бігати змагання за потужністю.', 'Recreational runners and athletes who want to train and race by power.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
