SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trainerroad.com' OR LOWER(`name`) = LOWER('TrainerRoad'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TrainerRoad', NULL, 'https://trainerroad.com', NULL, NULL, 'Застосунок для велотренувань: штучний інтелект підбирає тренування на кожен заїзд, прогнозує, наскільки важким воно буде з урахуванням історії, форми й відновлення, визначає FTP і допомагає уникати перевтоми.', 'A cycling training app: AI picks the workout for every ride, predicts how hard it will feel from your history, fitness and recovery, detects your FTP and helps prevent fatigue.', 'TrainerRoad — тренувальна система для велосипедистів, які хочуть стати швидшими. TrainerRoad AI проганяє сотні симуляцій, щоб знайти тренування, яке підходить саме вам, і в реальному часі підлаштовує план. Система прогнозує, наскільки важким буде кожне тренування, з огляду на вашу історію тренувань, результати й відновлення. Серед можливостей — автоматичне визначення порогової потужності FTP без окремого тесту, запобігання перевтомі, оптимізація на основі машинного навчання, щоденні рекомендації тренувань та інтерактивний календар. Тренування можна виконувати й усередині Zwift: достатньо один раз підключити акаунт, і заплановані AI тренування з''являться автоматично. Для старту не потрібен фітнес-тест. Є гарантія повернення коштів протягом 30 днів і можливість скасувати підписку будь-коли.', 'TrainerRoad is a training system for cyclists who want to get faster. TrainerRoad AI runs hundreds of simulations to find the workout that suits you best and adjusts your plan in real time. It predicts how hard each workout will feel based on your training history, performance and recovery. Features include AI FTP detection without a separate test, fatigue prevention, machine learning optimization, daily workout recommendations and an interactive training calendar. You can also ride TrainerRoad workouts inside Zwift: connect once and your AI-planned training shows up automatically. No fitness test is required to start. There is a 30-day money-back guarantee and you can cancel anytime.', 'AI-підбір тренування на кожен заїзд
Прогноз складності тренувань
Автоматичне визначення FTP
Запобігання перевтомі
Щоденні рекомендації й календар тренувань
Тренування всередині Zwift', 'AI workout selection for every ride
Workout difficulty prediction
Automatic FTP detection
Fatigue prevention
Daily recommendations and training calendar
Workouts inside Zwift', 'Велосипедисти будь-якого рівня, які хочуть системно підвищувати швидкість і потужність.', 'Cyclists of any level who want to systematically increase speed and power.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
