-- Welltory — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'welltory.com' OR LOWER(`name`) = LOWER('Welltory'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Welltory', NULL, 'https://welltory.com', NULL, NULL, 'Застосунок, який за даними телефона й носимих пристроїв показує, що забирає вашу енергію: аналіз серцевого ритму й тиску, рівень стресу й енергії, поради для сну й відновлення, оптимізація тренувань і раннє виявлення тривожних сигналів.', 'An app that uses phone and wearable data to show what drains your energy: heart rate and blood pressure analysis, stress and energy scores, sleep and recovery tips, workout optimization and early warning signs.', 'Welltory допомагає побачити, що забирає вашу енергію, і зупинити це до того, як воно зіпсує день. Застосунок перетворює понад 100 біомаркерів, отриманих зі смартфона й носимих пристроїв, на прості й практичні рекомендації. Він стежить за здоров''ям і попереджає про тривожні сигнали, аналізує зміни артеріального тиску, показує стан нервової системи в реальному часі, підказує, що знижує енергію і що її відновлює, допомагає глибше спати, підбирати оптимальну активність і тренування та стежити за довголіттям. Алгоритми перевірені в рецензованих дослідженнях і показують не просто цифри, а що вони означають для вашого життя сьогодні. Преміум-версія додає щоденні кроки до кращого здоров''я, поради при безсонні, головному болю чи паніці, персональні дослідження на основі ваших даних, дихальні практики, детальну аналітику серцевого ритму й звіти про тиск для лікаря.', 'Welltory helps you see what''s draining your energy and stop it before it drains your day. The app turns more than 100 biomarkers from your smartphone and wearables into simple, actionable guidance. It monitors your health and alerts you to warning signs, analyzes blood pressure changes, shows a real-time snapshot of your nervous system, reveals what lowers your energy and what restores it, helps you sleep more deeply, find the right activity and workouts, and track longevity. The algorithms are validated through peer-reviewed research and show not just numbers but what they mean for your life today. Premium adds daily steps toward better health, help with insomnia, headaches or panic, personalized research based on your data, breathing practices, detailed heart analytics and blood pressure reports for your doctor.', 'Аналіз понад 100 біомаркерів
Показники стресу, енергії й продуктивності
Аналіз артеріального тиску
Поради для сну й відновлення
Оптимізація тренувань
Дихальні практики
Звіти для лікаря', 'Analysis of 100+ biomarkers
Stress, energy and productivity scores
Blood pressure analysis
Sleep and recovery advice
Workout optimization
Breathing practices
Reports for your doctor', 'Люди, які хочуть стежити за енергією, стресом і відновленням, зокрема ті, хто тренується.', 'People who want to track energy, stress and recovery, including those who train.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
