-- Zone7 — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'zone7.ai' OR LOWER(`name`) = LOWER('Zone7'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Zone7', NULL, 'https://zone7.ai', NULL, NULL, 'AI-платформа для професійних спортивних організацій, яка аналізує дані про навантаження й допомагає керувати ним так, щоб гравці частіше були доступні для матчів, а ризик пропусків через травми знижувався.', 'An AI platform for pro sports organizations that analyzes workload data and helps manage it so players are available for matches more often and fewer games are missed through injury.', 'Zone7 — компанія з портфеля svexa, яка за допомогою штучного інтелекту допомагає високопрофесійним організаціям зберігати гравців здоровими й доступними для гри. Алгоритм працює поруч із внутрішньою системою моніторингу команди й дає рекомендації щодо керування навантаженням гравців, а розробники постійно його оновлюють і вдосконалюють. Фітнес-тренери професійних клубів використовують ці підказки як додаткову опору під час ухвалення рішень. Zone7 також проводить ретроспективний аудит, аналізуючи дані сезону команди, і публікує кейси — наприклад, як переможець кубка MLS покращив доступність гравців завдяки керуванню навантаженням на основі AI. Компанія досліджує й те, як AI може вплинути на ринок спортивного страхування. Рішення створене для професійних клубів і організацій високих досягнень.', 'Zone7, part of svexa''s performance intelligence portfolio, uses AI to help high-performance organizations keep players healthy and available. The algorithm works alongside a team''s internal monitoring system and provides recommendations on player load management, and it is constantly updated and refined. Fitness coaches at pro clubs use these insights as extra support when making decisions. Zone7 also runs retrospective performance audits of a team''s season data and publishes case studies, such as how an MLS Cup winner improved player availability through AI-informed load management. The company also explores how AI could affect sports insurance markets. It is built for pro clubs and high-performance organizations.', 'AI-аналіз навантаження гравців
Рекомендації щодо керування навантаженням
Підвищення доступності гравців
Інтеграція з внутрішнім моніторингом
Ретроспективний аудит сезону
Постійно оновлюваний алгоритм', 'AI analysis of player workload
Load management recommendations
Higher player availability
Integration with internal monitoring
Retrospective season audits
Constantly updated algorithm', 'Професійні футбольні й інші спортивні клуби, їхні фітнес-тренери й наукові штаби.', 'Pro football and other sports clubs, their fitness coaches and sport science staff.', 'web', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
