INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Zone7, part of svexa''s performance intelligence portfolio, uses AI to help high-performance organizations keep players healthy and available. The algorithm works alongside a team''s internal monitoring system and provides recommendations on player load management, and it is constantly updated and refined. Fitness coaches at pro clubs use these insights as extra support when making decisions. Zone7 also runs retrospective performance audits of a team''s season data and publishes case studies, such as how an MLS Cup winner improved player availability through AI-informed load management. The company also explores how AI could affect sports insurance markets. It is built for pro clubs and high-performance organizations.', 'manual' FROM DUAL WHERE @new = 1;
